using System.Collections.Generic;
using UnityEngine;

namespace Controllers.Rune
{
    /// <summary>
    /// 局外符文背包 — 存储玩家已收集的符文 ID，跨局持久化（PlayerPrefs）。
    /// 拾取符文时调用 AddRune()，在 RunePanel 或大厅中可读取 GetAllRuneIds() 展示。
    /// </summary>
    public static class RuneInventory
    {
        private const string PlayerPrefsKey = "RuneInventory_CollectedIds";

        /// <summary>获取所有已收集的符文 ID</summary>
        public static List<int> GetAllRuneIds()
        {
            var ids = new List<int>();
            string saved = PlayerPrefs.GetString(PlayerPrefsKey, "");
            if (string.IsNullOrEmpty(saved)) return ids;

            foreach (var part in saved.Split(','))
            {
                if (int.TryParse(part, out int id))
                    ids.Add(id);
            }
            return ids;
        }

        /// <summary>添加一个符文到背包（不去重，支持重复购买）</summary>
        public static void AddRune(int runeId)
        {
            var ids = GetAllRuneIds();
            ids.Add(runeId);
            Save(ids);
            Debug.Log($"[RuneInventory] 收集符文 ID={runeId}，当前背包共 {ids.Count} 个");
        }

        /// <summary>检查是否已拥有某个符文</summary>
        public static bool HasRune(int runeId) => GetAllRuneIds().Contains(runeId);

        /// <summary>清空背包（测试用）</summary>
        public static void Clear()
        {
            PlayerPrefs.DeleteKey(PlayerPrefsKey);
            PlayerPrefs.Save();
            Debug.Log("[RuneInventory] 背包已清空");
        }

        private static void Save(List<int> ids)
        {
            PlayerPrefs.SetString(PlayerPrefsKey, string.Join(",", ids));
            PlayerPrefs.Save();
        }
    }
}

using System.Collections.Generic;
using Core;
using Controllers.Rune;
using UnityEngine;

namespace Managers
{
  public class ShopManager : MonoBehaviour
  {
    public static ShopManager Instance { get; private set; }

    [Header("商店配置")]
    [SerializeField] private ShopRuneDatabaseSO shopDatabase;

    private Dictionary<int, int> purchaseRecords = new Dictionary<int, int>();

    void Awake()
    {
      if (Instance == null)
      {
        Instance = this;
        DontDestroyOnLoad(gameObject);
      }
      else
      {
        Destroy(gameObject);
      }
    }

    public bool PurchaseRune(int runeId)
    {
      var config = shopDatabase.GetRuneById(runeId);
      if (config == null)
      {
        Debug.LogError($"[ShopManager] 符文 ID={runeId} 不存在于商店数据库");
        return false;
      }

      if (!IsRuneAvailable(runeId))
      {
        Debug.Log($"[ShopManager] 符文 ID={runeId} 已售罄");
        return false;
      }

      if (!config.allowRepeatPurchase && RuneInventory.HasRune(runeId))
      {
        Debug.Log($"[ShopManager] 符文 ID={runeId} 已拥有，且不允许重复购买");
        return false;
      }

      if (!CoinManager.Instance.SpendCoins(config.price))
      {
        Debug.Log($"[ShopManager] 金币不足，无法购买符文 ID={runeId}");
        return false;
      }

      RecordPurchase(runeId);
      RuneInventory.AddRune(runeId);

      var eventData = new RunePurchasedEventData
      {
        runeId = runeId,
        price = config.price,
        remainingStock = GetRemainingStock(runeId)
      };
      EventChannelLocator.MainContainer?.shopEventChannel?.RaiseRunePurchased(eventData);

      Debug.Log($"[ShopManager] 购买成功：符文 ID={runeId}，花费 {config.price} 金币");
      return true;
    }

    public bool IsRuneAvailable(int runeId)
    {
      var config = shopDatabase.GetRuneById(runeId);
      if (config == null) return false;

      if (!config.isLimitedStock) return true;

      int remaining = GetRemainingStock(runeId);
      return remaining > 0;
    }

    public int GetRemainingStock(int runeId)
    {
      var config = shopDatabase.GetRuneById(runeId);
      if (config == null) return 0;

      if (!config.isLimitedStock) return -1;

      purchaseRecords.TryGetValue(runeId, out int purchased);
      return Mathf.Max(0, config.maxStock - purchased);
    }

    private void RecordPurchase(int runeId)
    {
      if (!purchaseRecords.ContainsKey(runeId))
      {
        purchaseRecords[runeId] = 0;
      }
      purchaseRecords[runeId]++;
    }

    public Dictionary<int, int> GetPurchaseRecords()
    {
      return purchaseRecords;
    }

    public void SetPurchaseRecords(Dictionary<int, int> records)
    {
      purchaseRecords = new Dictionary<int, int>(records);
    }
  }
}

using System.Collections.Generic;
using Controllers.Rune;
using UnityEngine;

[CreateAssetMenu(menuName = "Shop/Shop Rune Config")]
public class ShopRuneConfigSO : ScriptableObject
{
  [Header("基础符文数据")]
  public RuneDataSO runeData;

  [Header("商店配置")]
  public int price;
  public bool isLimitedStock;
  public int maxStock = 1;
  [Tooltip("勾选后允许重复购买（已拥有也可再次购买）")]
  public bool allowRepeatPurchase;

  public int runeId => runeData?.runeId ?? -1;
  public string runeName => runeData?.runeName ?? string.Empty;
  public Sprite icon => runeData?.icon;
  public Rarity quality => runeData?.rarity ?? Rarity.Common;
  public string description
  {
    get
    {
      if (runeData == null) return string.Empty;
      if (!string.IsNullOrEmpty(runeData.specialPowerDescription))
        return runeData.specialPowerDescription;

      if (runeData.powers == null || runeData.powers.Count == 0)
        return string.Empty;

      var parts = new List<string>();
      foreach (var power in runeData.powers)
      {
        parts.Add($"{(power.value > 0 ? "+" : "")}{power.value}{power.label}");
      }

      return string.Join("\n", parts);
    }
  }
}

