namespace Managers
{
  /// <summary>
  /// 存档总管 —— 统一管理所有数据的存/读/删。
  ///
  /// 职责：
  /// - 收集各个 Manager 的数据 → 写入硬盘
  /// - 从硬盘读取数据 → 分发给各个 Manager
  /// - 提供 SaveGame / LoadGame / DeleteGame / HasSave 接口
  ///
  /// 设计说明：
  /// - 单例 + DontDestroyOnLoad，全局唯一
  /// - 一个账号对应一个存档，文件名为 save.json
  /// - 账号系统暂未实现，暂时只有本地单存档
  /// - 与 FileDataHandler 组合使用，不直接操作文件
  /// </summary>
  public class SaveManager : MonoBehaviour
  {
    public static SaveManager Instance { get; private set; }

    [Header("存档配置")]
    [SerializeField] private bool useEncryption = false;

    private FileDataHandler fileHandler;
    private SaveData currentSaveData;

    private const string SAVE_FILE_NAME = "save";
    private const string SAVE_VERSION = "1.0.0";

    public static int SelectedCharacterIndex { get; set; } = 0;

    // ──────────────────────────────────
    //  单例生命周期
    // ──────────────────────────────────

    void Awake()
    {
      if (Instance == null)
      {
        Instance = this;
        DontDestroyOnLoad(gameObject);
        fileHandler = new FileDataHandler(UnityEngine.Application.persistentDataPath);
        currentSaveData = new SaveData();
      }
      else
      {
        Destroy(gameObject);
      }
    }

    void Start()
    {
      // 启动时自动加载存档，确保 SelectedCharacterIndex 等数据从文件恢复
      if (Instance == this && HasSave())
      {
        LoadGame();
      }
    }

    // ──────────────────────────────────
    //  公开 API
    // ──────────────────────────────────

    /// <summary>存档是否存在</summary>
    public bool HasSave()
    {
      return fileHandler.HasSave(SAVE_FILE_NAME);
    }

    /// <summary>
    /// 保存游戏 —— 从各个 Manager 收集数据，写入硬盘
    /// </summary>
    public void SaveGame()
    {
      CollectDataFromManagers();

      // 填入元数据
      currentSaveData.saveVersion = SAVE_VERSION;
      currentSaveData.saveTimestamp = System.DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");

      // 序列化
      string json = Newtonsoft.Json.JsonConvert.SerializeObject(currentSaveData, Newtonsoft.Json.Formatting.Indented);

      // 写文件
      fileHandler.Save(SAVE_FILE_NAME, json, useEncryption);

      Debug.Log($"[SaveManager] 存档成功 ({currentSaveData.saveTimestamp})");
    }

    /// <summary>
    /// 加载游戏 —— 从硬盘读取数据，分发给各个 Manager
    /// </summary>
    public void LoadGame()
    {
      string json = fileHandler.Load(SAVE_FILE_NAME, useEncryption);

      if (string.IsNullOrEmpty(json))
      {
        Debug.Log("[SaveManager] 没有存档，使用默认数据");
        currentSaveData = new SaveData();
        return;
      }

      // 反序列化
      currentSaveData = Newtonsoft.Json.JsonConvert.DeserializeObject<SaveData>(json);

      if (currentSaveData == null)
      {
        Debug.LogError("[SaveManager] 存档解析失败，使用默认数据");
        currentSaveData = new SaveData();
        return;
      }

      // 版本兼容处理
      HandleVersionCompatibility();

      // 分发数据
      DistributeDataToManagers();

      Debug.Log($"[SaveManager] 读档成功 ← ({currentSaveData.saveTimestamp})");
    }

    /// <summary>
    /// 删除存档
    /// </summary>
    public void DeleteGame()
    {
      fileHandler.Delete(SAVE_FILE_NAME);
      currentSaveData = new SaveData();
      Debug.Log("[SaveManager] 存档已删除");
    }

    /// <summary>
    /// 新建游戏 —— 重置所有数据为默认值
    /// </summary>
    public void NewGame()
    {
      currentSaveData = new SaveData();
      DistributeDataToManagers();
      Debug.Log("[SaveManager] 新建游戏，数据已重置");
    }

    // ──────────────────────────────────
    //  生涯数据查询与累加
    // ──────────────────────────────────

    /// <summary>获取生涯累计总经验值</summary>
    public int GetTotalExperience()
    {
      return currentSaveData.totalExperience;
    }

    /// <summary>获取生涯累计金币</summary>
    public int GetTotalCoin()
    {
      return currentSaveData.coin;
    }

    /// <summary>
    /// 对局结算时调用：累加本局获得的经验到生涯总经验
    /// </summary>
    /// <param name="matchExp">本局获得的经验值</param>
    public void AddMatchExperience(int matchExp)
    {
      if (matchExp <= 0) return;
      currentSaveData.totalExperience += matchExp;
      Debug.Log($"[SaveManager] 生涯经验 +{matchExp}，累计 {currentSaveData.totalExperience}");
    }

    /// <summary>获取存档中所有任务的累计进度</summary>
    public Dictionary<int, int> GetTaskProgress()
    {
      return currentSaveData.taskProgress;
    }

    // ──────────────────────────────────
    //  数据收集（存档时调用）
    // ──────────────────────────────────

    private void CollectDataFromManagers()
    {
      // 玩家经济
      if (CoinManager.Instance != null)
        currentSaveData.coin = CoinManager.Instance.GetCoins();

      // 符文系统
      currentSaveData.equippedRuneId1 = RuneEquipmentSnapshot.EquippedRuneId1;
      currentSaveData.equippedRuneId2 = RuneEquipmentSnapshot.EquippedRuneId2;

      // 任务进度（这是存档的核心用途——任务需要跨对局累积）
      if (QuestTaskManager.Instance != null)
        currentSaveData.taskProgress = QuestTaskManager.Instance.GetAllProgress();

      // 商店系统
      if (ShopManager.Instance != null)
        currentSaveData.shopPurchaseRecords = ShopManager.Instance.GetPurchaseRecords();

      // 累计统计
      if (MatchStatisticsManager.Instance != null)
      {
        var stats = MatchStatisticsManager.Instance.GetLifetimeStats();
        currentSaveData.lifetimeKills = stats.kills;
        currentSaveData.lifetimeDamage = stats.damage;
        currentSaveData.lifetimeMatches = stats.matches;
      }

      // 角色选择
      currentSaveData.selectedCharacterIndex = SelectedCharacterIndex;
    }

    // ──────────────────────────────────
    //  数据分发（读档时调用）
    // ──────────────────────────────────

    private void DistributeDataToManagers()
    {
      // 玩家经济
      if (CoinManager.Instance != null)
        CoinManager.Instance.SetCoins(currentSaveData.coin);

      // 符文系统
      RuneEquipmentSnapshot.SetBoth(currentSaveData.equippedRuneId1, currentSaveData.equippedRuneId2);

      // 任务进度
      if (QuestTaskManager.Instance != null)
        QuestTaskManager.Instance.SetAllProgress(currentSaveData.taskProgress);

      // 商店系统
      if (ShopManager.Instance != null)
        ShopManager.Instance.SetPurchaseRecords(currentSaveData.shopPurchaseRecords);

      // 累计统计
      if (MatchStatisticsManager.Instance != null)
        MatchStatisticsManager.Instance.SetLifetimeStats(
            currentSaveData.lifetimeKills,
            currentSaveData.lifetimeDamage,
            currentSaveData.lifetimeMatches
        );

      // 角色选择
      SelectedCharacterIndex = currentSaveData.selectedCharacterIndex;
    }

    // ──────────────────────────────────
    //  版本兼容
    // ──────────────────────────────────

    /// <summary>
    /// 当游戏更新后，旧存档可能缺少新字段，这里逐版本升级
    /// </summary>
    private void HandleVersionCompatibility()
    {
      // 空存档（极旧版本）
      if (string.IsNullOrEmpty(currentSaveData.saveVersion))
      {
        // 补全所有默认值
        if (currentSaveData.ownedCardIds == null)
          currentSaveData.ownedCardIds = new List<string>();
        if (currentSaveData.ownedRuneIds == null)
          currentSaveData.ownedRuneIds = new List<int>();
        if (currentSaveData.taskProgress == null)
          currentSaveData.taskProgress = new Dictionary<int, int>();

        currentSaveData.saveVersion = "1.0.0";
      }

      // 后续版本升级示例：
      // if (currentSaveData.saveVersion == "1.0.0")
      // {
      //     // 1.0.0 → 1.1.0 新增了某个字段
      //     currentSaveData.xxx = 默认值;
      //     currentSaveData.saveVersion = "1.1.0";
      // }
    }

    // ──────────────────────────────────
    //  游戏退出时自动存档
    // ──────────────────────────────────

    void OnApplicationQuit()
    {
      SaveGame();
    }
  }
}

using Core;
using UnityEngine;

namespace Managers
{
    /// <summary>
    /// 金币系统管理器（Application 层）
    ///
    /// 职责：
    /// - 管理金币的增删查（运行时内存值）
    /// - 提供金币计算公式 CalculateCoins(kills, totalDamage)
    /// - 通过 EventChannel 与 Presentation 层通信
    ///
    /// 持久化说明：
    /// - 不再使用 PlayerPrefs，由 SaveManager 统一管理
    /// - SaveManager.LoadGame() → SetCoins() 恢复
    /// - SaveManager.SaveGame() → GetCoins() 收集
    ///
    /// 通信方式：
    /// 输出 → coinUpdateChannel（金币变化时更新 UI）
    ///
    /// 设计说明：
    /// - 纯本地单例，无需网络同步
    /// - 只含一种货币（金币）
    /// - CalculateCoins() 为纯计算方法，不修改余额
    /// </summary>
    public class CoinManager : MonoBehaviour
    {
        public static CoinManager Instance { get; private set; }

        // ========== 配置项（Inspector 可调） ==========

        [Header("金币计算参数")]
        [SerializeField] private int baseCoinPerKill = 50;
        [SerializeField] private float damageCoinFactor = 0.1f;

        // ========== 运行时状态 ==========

        private int currentCoins;

        // ========== 单例生命周期 ==========

        void Awake()
        {
            if (Instance == null)
            {
                Instance = this;
                DontDestroyOnLoad(gameObject);
            }
            else
            {
                Destroy(gameObject);
            }
        }

        void OnDestroy()
        {
            if (Instance == this)
            {
                Instance = null;
            }
        }

        // ========== 公开 API ==========

        /// <summary>获取当前金币总数</summary>
        public int GetCoins()
        {
            return currentCoins;
        }

        /// <summary>增加金币，并触发 UI 更新</summary>
        public void AddCoins(int amount)
        {
            if (amount <= 0) return;

            currentCoins += amount;
            RaiseCoinUpdate(amount);
        }

        /// <summary>
        /// 消费金币
        /// </summary>
        /// <param name="amount">消费金额</param>
        /// <returns>是否消费成功（余额不足返回 false）</returns>
        public bool SpendCoins(int amount)
        {
            if (amount <= 0) return false;
            if (currentCoins < amount) return false;

            currentCoins -= amount;
            RaiseCoinUpdate(-amount);
            return true;
        }

        /// <summary>直接设置金币数（用于存档恢复、GM 指令等）</summary>
        public void SetCoins(int amount)
        {
            if (amount < 0) amount = 0;

            int delta = amount - currentCoins;
            currentCoins = amount;
            RaiseCoinUpdate(delta);
        }

        // ========== 金币计算公式 ==========

        /// <summary>
        /// 根据击杀数和总伤害计算应获得的金币数
        /// 公式：kills * baseCoinPerKill + floor(totalDamage * damageCoinFactor)
        /// </summary>
        /// <param name="kills">本局击杀数</param>
        /// <param name="totalDamage">本局总伤害量</param>
        /// <returns>经公式计算后应得的金币数</returns>
        /// <remarks>
        /// 此方法为纯计算，不修改余额。
        /// 调用方应使用返回值调用 AddCoins() 来实际发放金币。
        /// </remarks>
        public int CalculateCoins(int kills, int totalDamage)
        {
            int killReward = kills * baseCoinPerKill;
            int damageReward = Mathf.FloorToInt(totalDamage * damageCoinFactor);
            return killReward + damageReward;
        }

        /// <summary>重置金币为 0（用于测试）</summary>
        public void ResetCoins()
        {
            currentCoins = 0;
            RaiseCoinUpdate(0);
        }

        /// <summary>
        /// 广播当前金币数到事件通道，用于 UI 初始化。
        /// 进入大厅时调用，确保所有金币显示组件获得初始值。
        /// </summary>
        public void BroadcastCurrentCoins()
        {
            RaiseCoinUpdate(0);
        }

        // ========== 事件通信 ==========

        /// <summary>
        /// 发送金币更新事件到 Presentation 层
        /// </summary>
        private void RaiseCoinUpdate(int delta)
        {
            if (EventChannelLocator.MainContainer?.coinUpdateChannel == null) return;

            var data = new CoinUpdateData(currentCoins, delta);
            EventChannelLocator.MainContainer.coinUpdateChannel.Raise(data);
        }
    }
}

using System.Collections;
using Controllers.Item;
using UnityEngine;

namespace Controllers.Rune
{
    /// <summary>
    /// 符文掉落物 — 从敌人身上掉落，以抛物线轨迹飞出去然后落地
    /// 玩家靠近拾取后，符文效果即时应用到玩家属性
    /// </summary>
    public class DropItemRune : DropItemBase
    {
        [Header("符文数据")]
        [SerializeField] private RuneDataSO runeData;

        [Header("抛物线参数")]
        [SerializeField] private float launchAngleMin = 50f;       // 最小发射仰角（度）
        [SerializeField] private float launchAngleMax = 70f;       // 最大发射仰角（度）
        [SerializeField] private float launchSpeed = 6f;           // 发射初速度
        [SerializeField] private float launchRandomRadius = 3f;    // 落点随机散布半径
        [SerializeField] private float spinTorque = 3f;            // 飞行中的自旋扭矩

        [Header("落地检测")]
        [SerializeField] private float landVelocityThreshold = 0.2f; // 判定落地的速度阈值
        [SerializeField] private float groundCheckDistance = 2f;     // 向下检测地面的距离
        [SerializeField] private LayerMask groundLayer = -1;         // 地面层（-1 = Everything）
        [SerializeField] private float groundYOffset = 0.05f;        // 落地后离地高度

        [Header("生命周期")]
        [SerializeField] private float maxLifetime = 30f;           // 无人拾取时自动消失的时间


        [Header("子类特效")]
        [SerializeField] private GameObject trail;
        [SerializeField] private GameObject realyFx;
        // ── 运行时状态 ──
        private bool hasLanded = false;
        private float launchTime;               // 发射时刻（防 OnCollisionEnter 误触）
        private Coroutine landCheckCoroutine;
        private Coroutine lifetimeCoroutine;

        // ======================================================================
        //  Setup — 由敌人掉落时调用，传入掉落的符文数据
        // ======================================================================

        /// <summary>设置该掉落物对应的符文数据</summary>
        public void Setup(RuneDataSO data)
        {
            runeData = data;
        }

        /// <summary>获取该掉落物携带的符文数据</summary>
        public RuneDataSO GetRuneData() => runeData;

        // ======================================================================
        //  生命周期（继承自 DropItemBase）
        // ======================================================================

        /// <summary>
        /// GameObject 被激活时调用：
        /// 基类 OnEnable() 会重置飞行状态并调用 ApplyExplosionEffect()
        /// 我们 override ApplyExplosionEffect() 来实现抛物线
        /// </summary>
        protected override void OnEnable()
        {
            hasLanded = false;

            // 清除之前的协程
            if (landCheckCoroutine != null)
            {
                StopCoroutine(landCheckCoroutine);
                landCheckCoroutine = null;
            }
            if (lifetimeCoroutine != null)
            {
                StopCoroutine(lifetimeCoroutine);
                lifetimeCoroutine = null;
            }

            base.OnEnable();
        }

        protected override void OnDisable()
        {
            base.OnDisable();

            if (landCheckCoroutine != null)
            {
                StopCoroutine(landCheckCoroutine);
                landCheckCoroutine = null;
            }
            if (lifetimeCoroutine != null)
            {
                StopCoroutine(lifetimeCoroutine);
                lifetimeCoroutine = null;
            }
        }

        // ======================================================================
        //  抛物线弹射（override 基类的简单爆炸）
        // ======================================================================

        /// <summary>
        /// 重写基类的 ApplyExplosionEffect：
        /// 以高抛角度将符文弹射出去，形成抛物线轨迹
        /// </summary>
        protected override void ApplyExplosionEffect()
        {
            if (Rb == null)
                return;

            // 1. 重置物理状态
            Rb.velocity = Vector3.zero;
            Rb.angularVelocity = Vector3.zero;
            Rb.isKinematic = false;
            Rb.useGravity = true;

            // 记录发射时刻，防止 OnCollisionEnter 误触
            launchTime = UnityEngine.Time.time;

            // 2. 随机偏移落点方向（在敌人周围散布）
            Vector2 randomCircle = Random.insideUnitCircle.normalized;
            Vector3 horizontalDir = new Vector3(randomCircle.x, 0, randomCircle.y);

            // 3. 计算发射速度
            //    已知水平距离 distance，仰角 angle，初速度 launchSpeed
            //    水平分量: v_x = launchSpeed * cos(angle)
            //    垂直分量: v_y = launchSpeed * sin(angle)
            float angle = Random.Range(launchAngleMin, launchAngleMax);
            float angleRad = angle * Mathf.Deg2Rad;

            Vector3 launchVelocity = horizontalDir * launchSpeed * Mathf.Cos(angleRad)
                                   + Vector3.up * launchSpeed * Mathf.Sin(angleRad);

            // 4. 施加瞬时速度
            Rb.AddForce(launchVelocity, ForceMode.VelocityChange);

            // 5. 添加旋转（让符文在空中翻转）
            Rb.AddTorque(new Vector3(
                Random.Range(-1f, 1f),
                Random.Range(-1f, 1f),
                Random.Range(-1f, 1f)
            ) * spinTorque, ForceMode.VelocityChange);

            // 5.5 增加阻力，防止落地后滑行
            Rb.drag = 2f;
            Rb.angularDrag = 2f;

            // 6. 启动落地检测协程
            landCheckCoroutine = StartCoroutine(CheckLanding());

            // 7. 启动生命周期计时（超时自动消失）
            lifetimeCoroutine = StartCoroutine(AutoDespawnAfterDelay());
        }

        // ======================================================================
        //  落地检测
        // ======================================================================

        private IEnumerator CheckLanding()
        {
            // 给一个最小飞行时间，避免刚发射就被判定落地
            float minFlightTime = 0.4f;
            float timer = 0f;

            while (!hasLanded)
            {
                timer += UnityEngine.Time.deltaTime;

                // 条件 A：至少飞了 minFlightTime
                // 条件 B：速度很低
                // 条件 C：在地面附近（Raycast 检测）
                if (timer > minFlightTime && Rb.velocity.magnitude < landVelocityThreshold)
                {
                    // 向下发射射线检测地面
                    if (Physics.Raycast(transform.position, Vector3.down, out RaycastHit hit,
                            groundCheckDistance, groundLayer))
                    {
                        // 停在落地点正上方
                        transform.position = new Vector3(
                            transform.position.x,
                            hit.point.y + groundYOffset,
                            transform.position.z
                        );

                        OnLand();
                        yield break;
                    }
                    else
                    {
                        // 速度很低但不在"地面"上 — 可能卡在半空
                        // 再等一小段时间强制落地
                        yield return new WaitForSeconds(0.5f);

                        if (!hasLanded)
                        {
                            // 强制落地：使用当前位置的 Y 作为地面
                            OnLand();
                            yield break;
                        }
                    }
                }

                yield return null; // 每帧检测
            }
        }

        private void OnLand()
        {
            hasLanded = true;
            Debug.Log($"[DropItemRune] 符文落地: {runeData?.runeName ?? "未知符文"}");

            // 冻结物理，符文稳稳停住
            if (Rb != null)
            {
                Rb.velocity = Vector3.zero;
                Rb.angularVelocity = Vector3.zero;
                Rb.isKinematic = true;
                Rb.useGravity = false;
            }

            // 将 transform 摆正（防止歪着插地上）
            transform.rotation = Quaternion.identity;

            // 关闭拖尾特效
            if (trail != null)
                trail.SetActive(false);
            if (realyFx != null)
                realyFx.SetActive(true);
        }

        // ======================================================================
        //  物理碰撞落地（比协程的速度检测更可靠）
        // ======================================================================

        private void OnCollisionEnter(Collision collision)
        {
            if (hasLanded) return;

            // 最小飞行时间保护，防止刚生成就误触落地
            if (UnityEngine.Time.time - launchTime < 0.5f) return;

            // 检查碰撞的物体是否属于 groundLayer
            int layerMask = 1 << collision.gameObject.layer;
            if ((groundLayer.value & layerMask) != 0)
            {
                OnLand();
            }
        }

        // ======================================================================
        //  超时自动消失
        // ======================================================================

        private IEnumerator AutoDespawnAfterDelay()
        {
            yield return new WaitForSeconds(maxLifetime);

            // 如果还没被捡走，超时自动销毁
            if (!DropItemData.isFlyingToPlayer && hasLanded)
            {
                Debug.Log($"[DropItemRune] 符文超时消失: {runeData?.runeName ?? "未知"}");
                DespawnSelf();
            }
        }

        // ======================================================================
        //  拾取到达（override 基类）
        // ======================================================================

        /// <summary>
        /// 符文飞到玩家身边后调用 — 存入局外背包并销毁
        /// </summary>
        protected override void OnReachPlayer()
        {
            if (runeData != null)
            {
                Debug.Log($"[DropItemRune] 玩家拾取符文: {runeData.runeName} (ID={runeData.runeId})");

                // 存入局外背包（不应用局内效果）
                RuneInventory.AddRune(runeData.runeId);
            }

            DespawnSelf();
        }

        // ======================================================================
        //  回收（本地直接销毁）
        // ======================================================================

        private void DespawnSelf()
        {
            Destroy(gameObject);
        }

        // ======================================================================
        //  OnDestroy 清理协程（防止销毁后协程还在跑）
        // ======================================================================

        private void OnDestroy()
        {
            if (landCheckCoroutine != null)
            {
                StopCoroutine(landCheckCoroutine);
                landCheckCoroutine = null;
            }
            if (lifetimeCoroutine != null)
            {
                StopCoroutine(lifetimeCoroutine);
                lifetimeCoroutine = null;
            }
        }
    }
}

